    def wait_for_compute_operation(
        self,
        operation_id: str,
        *,
        workspace_id: str,
        timeout: float = 1200.0,
        poll_interval: float = 5.0,
        raise_on_failure: bool = True,
        on_update: typing.Optional[typing.Callable[[OperationStatus], None]] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> OperationStatus:
        """
        Polls a compute operation until it succeeds, fails, or ``timeout`` seconds pass.

        ``timeout`` is 1-7200 seconds (default 1200) and ``poll_interval`` 1-60 seconds
        (default 5). Raises ``OperationFailedError`` when the operation ends ``failed``,
        ``cancelled`` or ``timed_out`` (unless ``raise_on_failure=False``, which returns
        it), and ``OperationTimeoutError`` when the client stops waiting first.

        Examples
        --------
        from ibee import Ibee

        client = Ibee(
            token="YOUR_TOKEN",
        )
        accepted = client.gpu_vms.start_gpu_vm("65f1c2a9e4b0a1b2c3d4e5f6", workspace_id="710995")
        client.gpu_vms.wait_for_compute_operation(accepted.operation_id, workspace_id="710995")
        """
        return wait_for_compute_operation(
            self,
            operation_id,
            workspace_id=workspace_id,
            timeout=timeout,
            poll_interval=poll_interval,
            raise_on_failure=raise_on_failure,
            on_update=on_update,
            request_options=request_options,
        )

