    async def wait_for_compute_operation(
        self,
        operation_id: str,
        *,
        workspace_id: str,
        timeout: float = 1200.0,
        poll_interval: float = 5.0,
        raise_on_failure: bool = True,
        on_update: typing.Optional[typing.Callable[[OperationStatus], typing.Any]] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> OperationStatus:
        """
        Polls a compute operation until it succeeds, fails, or ``timeout`` seconds pass.

        Same semantics as the synchronous client's ``wait_for_compute_operation``.
        """
        return await wait_for_compute_operation_async(
            self,
            operation_id,
            workspace_id=workspace_id,
            timeout=timeout,
            poll_interval=poll_interval,
            raise_on_failure=raise_on_failure,
            on_update=on_update,
            request_options=request_options,
        )

